@staticmethod
def _get_century_code(year: int) -> str:
    """Returns the century code for a given year."""
    if 1800 <= year < 1900:
        return "+"
    elif 1900 <= year < 2000:
        return "-"
    elif 2000 <= year < 3000:
        return "A"
    raise ValueError("Finnish SSN does not support years before 1800 or after 2999")
